#include <bits/stdc++.h>
#define endl '\n'

using namespace std;

using ll = long long;

const ll N = 2e5 + 5;

int n, m, head[N], deg[N], d[N], a[N], p;
ll val[N], ans, sum, res;
bool del[N];
string s;
queue<int> q;
struct
{
	int v, w, next;
} e[N << 1];

void add(int u, int v, int w)
{
	static int cnt = 0;
	e[++cnt] = {v, w, head[u]};
	head[u] = cnt;
}

void init() {}

void solve()
{
	cin >> n >> s;
	m = n + 1;
	s = "0" + s + "0";
	for (int i = 1; i <= m; ++i)
		d[i] = (s[i] - 48) ^ (s[i - 1] - 48);
	for (int i = 1, l, r; i <= m; ++i)
	{
		cin >> l >> r >> val[i];
		add(l, r + 1, i);
		add(r + 1, l, i);
		++deg[l], ++deg[r + 1];
	}
	for (int i = 1; i <= m; ++i)
	{
		if (deg[i] == 1)
			q.push(i);
	}
	for (int u; q.size();)
	{
		u = q.front();
		q.pop();
		for (int i = head[u], v, w; i; i = e[i].next)
		{
			if (del[w = e[i].w])
				continue;
			a[w] = d[u];
			ans += val[w] * a[w];
			d[v = e[i].v] ^= a[w];
			del[w] = 1;
			--deg[u];
			if (--deg[v] == 1)
				q.push(v);
			break;
		}
	}
	{
		int i, w, st = 1, u = st, pre = 0, x = 0;
		p = m + 1;
		while (deg[st] != 2)
			++st;
		u = st;
		do
		{
			i = head[u];
			while (del[e[i].w] || e[i].w == pre)
				i = e[i].next;
			w = e[i].w;
			a[w] = x;
			sum += val[w];
			res += val[w] * x;
			p = min(p, w);
			pre = w;
			u = e[i].v;
			x ^= d[u];
		} while (u != st);
	}
	if (res > sum - res || (res == sum - res && a[p]))
	{
		ans += sum - res;
		for (int i = 1; i <= m; ++i)
		{
			if (!del[i])
				a[i] ^= 1;
		}
	}
	else
		ans += res;
	cout << ans << endl;
	for (int i = 1; i <= m; ++i)
		cout << a[i];
	cout << endl;
}

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	cout.tie(nullptr);
	// freopen("uniflip.in", "r", stdin);
	// freopen("uniflip.out", "w", stdout);
	int _ = 1;
	// cin >> _;
	init();
	while (_--)
		solve();
	return 0;
}
